function Create(){const steps=[['01','Define your identity','Choose a name, mission and operating style. Decide what makes your organisation different and who it is for.'],['02','Build the operation','Set realistic activity expectations, pilot onboarding, flight logging standards, route networks and staff responsibilities.'],['03','Create your home base','Launch a website or crew portal, publish your rules and create a reliable place for pilots to communicate.'],['04','Recruit with intention','Bring in a dependable founding team. Make roles clear and give pilots a welcoming first flight.'],['05','Make it sustainable','Plan events, staff succession, support and a healthy activity model before scaling up.'],['06','Apply to IVA','When your foundations are ready, submit an application. Our team will review your organisation and share next steps.']];return <><HeroPage n="05" eyebrow="START WITH A CLEAR FLIGHT PLAN" title="Creating a" em="VA / VO." body="A practical guide to building a virtual airline or organisation that people want to be part of."/><section className="creation section-pad"><div className="creation-intro"><Eyebrow>THE FOUNDING CHECKLIST</Eyebrow><h2>Build the culture<br/>before the <em>livery.</em></h2><p>A memorable VA is more than a name and a logo. Start with a clear purpose, consistent operations and a team that cares about its pilots.</p></div><div className="creation-steps">{steps.map(x=><div className="creation-step"><span>{x[0]}</span><div><h3>{x[1]}</h3><p>{x[2]}</p></div><ChevronRight/></div>)}</div></section><section className="creation-callout"><div><Eyebrow light>READY FOR TAKEOFF?</Eyebrow><h2>Make your idea<br/>an <em>organisation.</em></h2></div><Btn to="/apply" kind="white">Start your application</Btn></section></>}
